import { randomUUID } from 'node:crypto';
import { providerForPath } from './provider.js';
import { safeLine } from './safe-text.js';

const MAX_ACTIVE = 256;
const MAX_RECENT = 100;
const ACTIVITY_HOOKS = ['onRequestStart', 'onRequestModel', 'onRequestRouted', 'onRequestEnd'];

function requestPath(value) {
  return String(value || '').split(/[?#]/)[0].replace(/^\/tc-acct\/[^/]+(?=\/)/, '');
}

function publicPath(value) {
  const path = requestPath(value);
  // Publish only known API endpoint names. Arbitrary path segments can contain
  // private data just as query strings can; neither belongs in a status view.
  const known = /^\/(?:v1\/(?:messages(?:\/count_tokens)?|models|complete)|backend-api\/codex\/(?:responses(?:\/compact)?|models)|api\/event_logging(?:\/batch)?)$/;
  return known.test(path) ? safeLine(path, 240) : '(other)';
}

function text(value, max = 120) {
  return value == null ? null : safeLine(value, max);
}

/** Ephemeral, bounded request metadata. Credentials, prompts, responses,
 * session ids and client/dimension headers never enter this object. */
export class ActivityTracker {
  constructor({ now = Date.now } = {}) {
    this.instanceId = randomUUID();
    this.now = now;
    this.active = new Map();
    this.recent = [];
    this.lastRoutedAccounts = {};
    this.droppedActive = 0;
  }

  onRequestStart(id, info = {}) {
    if (!this.active.has(id) && this.active.size >= MAX_ACTIVE) {
      // The display must stay bounded even if many connections are held open.
      // Eviction affects observation only; it never cancels or delays a call.
      this.active.delete(this.active.keys().next().value);
      this.droppedActive++;
    }
    this.active.set(id, {
      id,
      provider: providerForPath(requestPath(info.path)),
      method: text(info.method, 16),
      path: publicPath(info.path),
      account: null,
      model: null,
      effort: null,
      pinned: !!info.pinned,
      startedAt: new Date(this.now()).toISOString(),
      endedAt: null,
      durationMs: null,
      status: null,
    });
  }

  onRequestModel(id, info = {}) {
    const row = this.active.get(id);
    if (row && info.model) row.model = text(info.model);
    if (row && info.effort) row.effort = text(info.effort, 24); // (local patch 2026-09-07 IRIS)
  }

  onRequestRouted(id, info = {}) {
    const row = this.active.get(id);
    const provider = info.provider === 'codex' || info.provider === 'anthropic' ? info.provider : row?.provider;
    const account = text(info.account);
    if (row) {
      row.account = account;
      if (provider) row.provider = provider;
    }
    // A routed event can outlive an evicted active row, or belong to hidden
    // telemetry. Provider metadata still identifies the actual selected pool.
    if (provider && account) this.lastRoutedAccounts[provider] = account;
  }

  onRequestEnd(id, info = {}) {
    const row = this.active.get(id);
    this.active.delete(id);
    if (this.recent.some(r => r.id === id)) return;
    const ended = this.now();
    const started = row?.startedAt ? Date.parse(row.startedAt) : null;
    this.recent.unshift({
      id,
      provider: row?.provider || providerForPath(requestPath(info.path)),
      method: text(info.method, 16) || row?.method || null,
      path: info.path == null ? (row?.path || '(other)') : publicPath(info.path),
      account: text(info.account) || row?.account || null,
      model: text(info.model) || row?.model || null,
      effort: row?.effort || null,
      pinned: info.pinned == null ? !!row?.pinned : !!info.pinned,
      startedAt: row?.startedAt || null,
      endedAt: new Date(ended).toISOString(),
      durationMs: started == null ? null : Math.max(0, ended - started),
      status: Number.isFinite(info.status) ? info.status : null,
    });
    if (this.recent.length > MAX_RECENT) this.recent.length = MAX_RECENT;
  }

  snapshot() {
    return {
      instanceId: this.instanceId,
      active: [...this.active.values()].map(row => ({ ...row })),
      recent: this.recent.map(row => ({ ...row })),
      lastRoutedAccounts: { ...this.lastRoutedAccounts },
      droppedActive: this.droppedActive,
    };
  }
}

/** Add metadata observation without replacing existing TUI/file-log hooks. */
export function withActivityHooks(hooks, tracker) {
  const combined = { ...hooks };
  for (const name of ACTIVITY_HOOKS) {
    const previous = hooks[name];
    combined[name] = function (id, info) {
      // Monitoring is never allowed to fail inference, nor to suppress an
      // existing hook. Preserve the existing callback's result and errors.
      try { tracker[name](id, info); } catch { /* observation only */ }
      return previous?.call(this, id, info);
    };
  }
  return combined;
}
